"""魚我所欲也：逐題人工編寫解析與錯項理由。"""
import json,copy
from pathlib import Path
HERE=Path(__file__).resolve().parent
BASE=json.loads((HERE/'baseline-bank.json').read_text(encoding='utf-8'))
QS=[q for q in BASE['questions'] if 'essay-02' in q['essayIds']]
SPECS={}
def put(n,ex,wrong,texts=None,**extra):
 q=QS[n-1];assert n not in SPECS and len(wrong)==3
 it=iter(wrong);choices=[]
 for i,c in enumerate(q['choices']):
  choices.append(dict(id=c['id'],text=texts[i] if texts else c['text'],explanation=ex.split('。')[0]+'。' if c['id']==q['answerId'] else next(it)))
 SPECS[n]=dict(explanation=ex,summary=ex.split('。')[0]+'。',choices=choices,**extra)

put(51,'何加焉追問不辨禮義接受萬鍾究竟有何增益，質疑的是用豐厚利益抵銷失義的想法。下文列出的享受和感激，正供讀者衡量是否值得失去本心。反問不是否認錢糧有任何生活用途，而是否定這些用途足以合理化失義。',['原文列受祿動機，沒有要求俸祿先分配給家人窮人的制度。','官位是否與待遇相稱不是此句的問題，合不合義才是判準。','原文未論辭官限制，不能將何加理解成是否可以離職。'])
put(52,'生亦我所欲、義亦我所欲兩句短而整齊，先讓讀者看清兩者並列；後面再接不可兼得和舍生取義，把條件與選擇說完整。句式由對稱走向展開，使節奏有變化又服務說理。不能只數字數而說每句等長，或憑語氣杜撰死亡迫近的場景。',['開頭没有羅列歷史事例，而是並列兩項所欲，後文才說取捨。','各句長短及結構並不全同，並列也不意味選擇毫無代價。','句子不是逐次縮短，原文亦未描寫死亡正在逼近的情節。'])
put(53,'為在何不為也中是做、實行，省略的對象是前面的避患之事。假設沒有比死亡更可惡的事，便會問有甚麼避患手段不去做。它是實際行動的動詞，不是為了某個目的的介詞，也沒有被誰施加行為的被動關係。',['為了須引出目的，這裏何不為問的是甚麼事不去做。','因為引原因，但本句為位於不之後，表示被否定的行動。','沒有被動施事者，主體是在考慮自己是否實行避患方法。'])
put(54,'第一個為引出宮室之美這個目的，意思是為了得到華美居所；後一個為之才說做這件事，即接受不合禮義的厚祿。分清目的與行動，才能看出孟子批評人為享受而改變準則，而非單純說房屋已經建成。',['做、實行是後一個為的作用，第一個為是在引出目的。','此處宮室之美是想求得的好處，不是已發生的事件原因；依本題來源以為了解。','原句是人主動為利益接受，不是被房屋施加行動的被動句。'])
put(55,'「今為宮室之美為之」後一個為是實行，為之在這裏指接受不合禮義的厚祿。前一個為引出想求的享受，後一個為說因此做了甚麼。題目雖把鄉句一併列出，所考仍是今句末的為，不能按整段第一個同字套義。',['為求美宅解釋的是今句前一個為所引的目的，未解後面的動詞。','宮室之美是動機，不是人變成房屋的結果，為並非成為。','替人辦事需要代誰行事的對象，為之在此說本人接受厚祿。'],targetStart=QS[54]['quote'].index('為之'))
put(56,'之代前面的重義本心，非獨賢者有是心、人皆有之兩句前後相接，對象相同而範圍擴大。人人都有不等於人人都能保有，所以後面還須補賢者能勿喪。找指代要回看是心，不是把之任意換成文章出現過的利益或方法。',['地位不是人皆有的對象，前句已以是心明示所指。','萬鍾在後段才出現，也不是孟子所說人人天生都有的東西。','求生方法和重義之心不同，之承前句是心而非前面一切內容。'])
put(57,'此之謂是這就叫作，整句把前面為利而失義的轉變定名為失其本心。之在這個結構中不是再代一個它，不能把此、之都當人物代詞。先把整個句式讀通，再問此概括了甚麼，才能接回前文鄉今選擇的矛盾。',['謂在此是稱作，不是說某句話提到了某事，否則失去歸結判斷。','此承前述做法，之也不是前往，原句没有人物出行。','失其本心是批評而非稱讚，這項將判斷方向讀反。'])
put(58,'於在甚於生中引出比較對象，相當於比，所欲有甚於生者就是有比生命更想要的東西。甚與於配合建立高低，才支撐後文不苟且求生。若讀成在或被，就無法保留義和生命的價值比較。',['生在此是比較標準，不是事情發生的地點或時間。','對於只標關涉對象，未表達甚於所需的超過比較。','原句沒有被動行為，於不是引出施事者。'])
put(59,'於我表示對於我，將萬鍾帶來的增益放在我這個受益者身上檢視。何加焉問有甚麼好處，不是問厚祿比我多多少，也不是因我而產生厚祿。相同於字須連同動詞關係判斷，不能一律套用甚於生的比字義。',['此句沒有將萬鍾與我比較高低，於我是在指出益處所及的人。','我不是厚祿發生的原因，於也不在此引出因果。','句子並非被我增加俸祿，沒有這項被動施受關係。'])
put(60,'所欲是所加動詞形成的名詞性結構，指想要的事物，魚正是其中一項。所不是這句中的地點名詞，欲也沒有被改成時間或方式。把整組換成我想要的東西，便可看清魚與所欲之間的判斷關係。',['所可在別處說處所，但所欲整體指欲的對象，不是地方。','方式回答怎樣想要，原句要回答想要甚麼，兩者不同。','原句沒有何時想要的時間關係，所欲是事物的名詞性表達。'])
put(61,'得生是獲得生存，承接人欲生的假設，指透過某些方法保全自己的生命。生不是新生嬰兒，得也不是天生已有；方法是否能使人活下來才是後面用不用的判斷起點。句子再藉有人拒用，說明求生仍受道義限制。',['生在此指生存狀態，不是可被取得的新生兒，應接回前文生命的議題。','生來擁有把生改成出生時間，並未保留得生的求生動作。','全段推論本人如何求生，未明說救的是他人的生命。'])
put(62,'用是採用，省略的對象是凡可以得生者，即能使人活下來的方法。何不用的反問在假設生命最高時推出所有有效手段都會採用，並非孟子最後鼓勵不擇手段。讀短句要補回前文對象，才能辨任用人才等其他用法。',['此句沒有可任用的人才，用所承的是求生方法。','消耗財物只是用的一種現代搭配，前文未把財物列作受用對象。','需要救助改成求援關係，未保留採用方法的動作。'],stem='「則凡可以得生者，何不用也」中的「用」應怎樣理解？')
put(63,'是故是因此，承接有效方法仍有人不用、不為的情況，推出人有比生死更重的原則。它標明從證據走向結論的因果關係，不是開啟時間或讓步。也要和由是分開：由是指依循那些方法，是故才負責總結推論。',['從前是時間，原句是在歸結前文推論，不是轉回昔日。','雖然引讓步，後面通常仍需轉折，此句則直接提出所得結論。','何故是在詢問原因，是故在這裏已作肯定的因此。'])
put(64,'食在一簞食中是飯食，前面的簞是盛載它的容器，因此這裏作名詞。它不是吃或餵這兩個動作，也不是後面的萬鍾俸祿。詞義要看搭配：一簞修飾多少食物，並不表示吃一次或餵某個人。',['吃飯作動詞，與一簞這個容器份量的修飾關係不合。','餵食需要被餵的對象，本句只列出飯食，沒有餵的動作。','俸祿是後段萬鍾所指，這裏是一小份能救命的食物。'])
